import json
from pathlib import Path
W=Path(__file__).resolve().parent
def rd(n):return json.loads((W/n).read_text('utf8'))
assets=rd('assets.json');spec={};inspection=[]
descs={
'SRPC-01.webp':('Phillips graph with downward SRPC0, vertical LRPC, and their intersection A.','The horizontal axis is Unemployment rate (%) from 0 to 10; the vertical axis is Inflation rate (%) from −2.5 to 10. Blue SRPC0 is a straight downward-sloping line through (0,6.5), A at (5,2.5), and (10,−1.5). Green LRPC is vertical at unemployment 5. Dashed guides from A mark 5 on the horizontal axis and 2.5 on the vertical axis.'),
'SRPC-02.webp':('Phillips graph with A and B on SRPC0 and vertical LRPC through A.','The horizontal axis is Unemployment rate (%) and the vertical axis is Inflation rate (%). Blue SRPC0 is a straight downward-sloping line from (0,5) through B at (3,3.5) and A at (5,2.5) to (10,0). Green LRPC is vertical at unemployment 5 and passes through A. B lies above and left of A on the same curve. Dashed horizontal and vertical guides mark both point coordinates.'),
'SRPC-03.webp':('Phillips graph with A and B on SRPC0 and vertical LRPC through A.','The horizontal axis is Unemployment rate (%) and the vertical axis is Inflation rate (%). Blue SRPC0 is a straight downward-sloping line from (0,5) through A at (5,2.5) and B at (7,1.5) to (10,0). Green LRPC is vertical at unemployment 5 and passes through A. B lies below and right of A on the same curve. Dashed horizontal and vertical guides mark both point coordinates.'),
'SRPC-04.webp':('Phillips graph with two downward-sloping SRPCs, vertical LRPC, and points A and B.','The horizontal axis is Unemployment rate (%) from 0 to 10; the vertical axis is Inflation rate (%) from 0 to 10. Solid blue SRPC0 is a straight downward-sloping line through (0,6), A at (5,3), and (10,0). Dashed purple SRPC1 is parallel above it, running through (0,9.6), B at (6,6), and (10,3.6). Green LRPC is vertical at unemployment 5 and intersects SRPC0 at A and SRPC1 at inflation 6.6. Dashed guides mark A at (5,3) and B at (6,6).')}
for a in assets:
 d=descs.get(a['filename']);after=dict(imageAlt=d[0],graphDescription=d[1]) if d else {k:a[k] for k in ['imageAlt','graphDescription']}
 for k in [a['runtimePath'],a['sourceAssetPath']]:spec[k]=after
 inspection.append(dict(runtimePath=a['runtimePath'],filename=a['filename'],sha256=a['sha256'],visuallyInspected=True,bytesChanged=False,contractCorrected=bool(d),reason='Complete axes, line coordinates, point guides and LRPC evidence missing from the short numerical-graph contract.' if d else 'Retain the correct detailed symbolic axes, point-to-curve mappings and dashed guides; deliver the same contract after path repair.',before={k:a[k] for k in ['imageAlt','graphDescription']},after=after))
for name,data in [('accessibility-spec.json',spec),('accessibility-inspection.json',inspection)]: (W/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n','utf8')
p=(W.parent/'.saving-work/stage.mjs').read_text('utf8').replace('.saving-work','.phillips-work').replace('total===268','total===262').replace('graphCount:60','graphCount:66').replace('Saving, Investment, Budgets & Debt audit validation','Phillips Curve, Expectations & Disinflation audit validation').replace('macro-saving-investment-budgets-debt-audit','phillips-expectations-disinflation-audit')
p=p.replace("reason:s?.reason||'Synchronize inline accessibility metadata with the visually verified approved asset contract.'", "reason:s?.reason||(old.image!==q.image?'Repair legacy image reference and deliver its visually verified registered accessibility contract.':'Complete inline accessibility with the inspected graph evidence.')")
p=p.replace("const oldViews=", "const parentRecipe={...recipe,selectedConceptIds:read('live-preset.json').selectedConceptIds};\nconst parentBefore=core.compose(base,parentRecipe),parentAfter=core.compose(lib,parentRecipe);\nassert(same(parentBefore.counts,parentAfter.counts)&&same(parentBefore.validation,parentAfter.validation)&&same(parentBefore.errors,parentAfter.errors),'Parent preset readiness changed');\nwrite('parent-preset-validation.json',{counts:parentAfter.counts,modes:parentAfter.validation,errors:parentAfter.errors,unchanged:true});\nconst oldViews=")
(W/'stage.mjs').write_text(p,'utf8')
p=(W.parent/'.saving-work/browser.cjs').read_text('utf8').replace('.saving-work','.phillips-work').replace('43297','PG5-PC-L-006');(W/'browser.cjs').write_text(p,'utf8')
print('Six image families inspected; four registered contracts expanded; long symbolic evidence retained.')
